#pragma once

/**
 * @file security_event.hpp
 * @brief This header file defines the SecurityEvent structure and related enumerations.
 *
 * The SecurityEvent structure represents a security event generated by an agent, including its type,
 * agent ID, and sequence number. The EventType enumeration defines the possible types of security events.
 *
 * @note The implementation of any related functions or methods is expected to be provided in a corresponding source file (e.g., security_event.cpp).
 *
 * @author Roberto Garzone
 * @date 2026-09-03
 */

#include <cstdint>

namespace sentinelgrid::engine {

	/**
	 * @brief An enumeration representing the types of security events.
	 */
	enum class EventType : std::uint32_t {
		heartbeat = 1,
		login_failed = 2,
		service_stop = 3
	};

	/**
	 * @brief A structure representing a security event.
	 *
	 * The SecurityEvent structure contains information about a security event generated by an agent,
	 * including the agent ID, sequence number, and event type.
	 */
	struct SecurityEvent {
		std::uint32_t agent_id{};
		std::uint64_t sequence_number{};
		EventType type{};
	};
}